using System;
using System.Collections.Generic;
using System.Data.SqlClient;
using System.Threading.Tasks;

public class SqlService : ISqlService
{
    private readonly IConnectionFactory _connectionFactory;
    private readonly ILogger _logger;

    public SqlService(IConnectionFactory connectionFactory, ILogger logger)
    {
        _connectionFactory = connectionFactory;
        _logger = logger;
    }

    public async Task ExecuteParameterizedQueryAsync(string commandText, List<SqlParameter> parameters, Action<string> onError)
    {
        using (var connection = _connectionFactory.CreateConnection())
        {
            await connection.OpenAsync();

            if (!connection.State.Equals(System.Data.ConnectionState.Open))
            {
                _logger.LogError("Database connection failed to open.");
                onError($"Database connection failed: {connection.ConnectionString}");
                return;
            }

            using (var command = new SqlCommand(commandText, connection))
            {
                foreach (var parameter in parameters)
                {
                    command.Parameters.Add(parameter);
                }

                try
                {
                    await command.ExecuteNonQueryAsync();
                }
                catch (Exception ex)
                {
                    _logger.LogError($"Error executing parameterized query: {ex.Message}");
                    onError($"Query execution failed: {ex.Message}");
                }
            }
        }
    }
}

public interface ISqlService
{
    Task ExecuteParameterizedQueryAsync(string commandText, List<SqlParameter> parameters, Action<string> onError);
}

public interface IConnectionFactory
{
    SqlConnection CreateConnection();
}
``` 



