['```C#
using System;
using System.Collections.Concurrent;
using System.Net.Http;
using System.Threading.Tasks;

public interface IGameEngineConfigurationService
{
    Task<GameEngineConfig> GetConfigAsync(string engineName);
}

public class GameEngineConfigurationService : IGameEngineConfigurationService
{
    private readonly HttpClient _httpClient;
    private readonly ConcurrentDictionary<string, GameEngineConfig> _cache = new();
    private readonly string _apiEndpoint;
    private readonly int _maxRetries = 3;
    private readonly TimeSpan _retryDelay = TimeSpan.FromSeconds(2);

    public GameEngineConfigurationService(string apiEndpoint)
    {
        _apiEndpoint = apiEndpoint;
        _httpClient = new HttpClient();
    }

    public async Task<GameEngineConfig> GetConfigAsync(string engineName)
    {
        if (_cache.TryGetValue(engineName, out var config))
        {
            return config;
        }

        var retryCount = 0;
        while (retryCount < _maxRetries)
        {
            try
            {
                var response = await _httpClient.GetAsync($"{_apiEndpoint}/{engineName}");
                response.EnsureSuccessStatusCode();
                var content = await response.Content.ReadAsStringAsync();
                config = JsonSerializer.Deserialize<GameEngineConfig>(content);

                _cache.TryAdd(engineName, config);
                return config;
            }
            catch (Exception ex)
            {
                Console.WriteLine($"Error fetching config for {engineName}: {ex.Message}");
                retryCount++;
                await Task.Delay(_retryDelay);
            }
        }

        throw new Exception($"Failed to retrieve config for {engineName} after {_maxRetries} retries.");
