// TestRunner.js

const { Worker } = require('worker_threads');
const blueslip = require('blueslip'); // Assuming a mocking library named 'blueslip'

class TestRunner {
  constructor(modulePath) {
    this.modulePath = modulePath;
    this.testQueue = [];
    this.concurrentLimit = 10;
    this.semaphore = new Semaphore(this.concurrentLimit);
  }

  async addTest(moduleName, testName, func) {
    this.testQueue.push({ moduleName, testName, func });
    this.runNextTest();
  }

  async runNextTest() {
    if (this.semaphore.available()) {
      const test = this.testQueue.shift();
      try {
        await this.loadModule(test.moduleName); // Dynamically load module
        // Execute test and log results
        console.log(`Running ${test.moduleName} - ${test.testName}`);
        await test.func();
        console.log(`Finished ${test.moduleName} - ${test.testName} (Pass)`);
      } catch (error) {
        console.error(`Failed ${test.moduleName} - ${test.testName}:`, error);
      } finally {
        this.semaphore.release(); // Release semaphore for concurrency control
        blueslip.reset(); // Reset mocks after each test
        this.runNextTest(); // Run the next test in the queue
      }
    }
  }

  async loadModule(moduleName) {
    try {
      const module = await import(/* webpackChunkName: "module-name" */ moduleName);
      return module; 
    } catch (error) {
      console.error(`Failed to load module ${moduleName}:`, error);
    }
  }
}


// Simple Semaphore implementation for concurrency control
class Semaphore {
  constructor(limit) {
    this.available = new Array(limit).fill(true);
  }

  acquire() {
    for (let i = 0; i < this.available.length; i++) {
      if (this.available[i]) {
        this.available[i] = false;
        return;
      }
    }
  }

  release() {
    const index = this.available.indexOf(false); 
    this.available[index] = true;
  }

  get available() {
    return this.available.filter(b => b).length;
  }
}


// Example Usage:
const runner = new TestRunner('./modules/module1'); // Replace with your module path

runner.addTest('Module1', 'testFunction1', async () => {
  // Write your test logic here...
}); 
