async function renderFooterScripts(scripts) {
  const footer = document.createElement('footer');

  const scriptCache = new Map(); // Cache fetched metadata

  for (const script of scripts) {
    if (!script.id || !script.code) {
      console.error('Invalid script object:', script);
      continue;
    }

    // Fetch metadata from API, handle errors and cache results
    let metadata = scriptCache.get(script.id);
    if (!metadata) {
      try {
        const response = await fetch(`https://api.example.com/script/${script.id}`);
        metadata = await response.json();
        scriptCache.set(script.id, metadata);
      } catch (error) {
        console.error('Error fetching metadata:', error);
        metadata = { name: 'Unknown', version: 'N/A', author: 'Unknown' }; // Fallback values
      }
    }

    // Create and append script tag with sanitized code and metadata
    const scriptElement = document.createElement('script');
    scriptElement.type = 'module';
    scriptElement.id = script.id;
    scriptElement.src = URL.createObjectURL(new Blob([script.code], { type: 'text/javascript' })); 

    // Add metadata attributes (sanitize if needed)
    Object.entries(metadata).forEach(([key, value]) => {
      scriptElement.setAttribute(`data-${key}`, value);
    });

    footer.appendChild(scriptElement);
  }

  document.body.appendChild(footer); 
}


// Example usage:
const scripts = [
  { id: 'script1', code: 'console.log("Hello from script1!")', name: 'My First Script', version: '1.0' },
  // ... more script objects ...
];

renderFooterScripts(scripts); 
