angular.module('myApp').service('dataRefresher', function ($http, $q) {
  const fieldIds = ['field1', 'field2', 'field3'];

  this.refreshFields = function() {
    const promises = fieldIds.map(id => {
      return $http.get(`api/fields/${id}`).then(response => response.data);
    });

    return Promise.all(promises).catch(error => {
      // Handle API errors gracefully (e.g., retry with exponential backoff)
      console.error('API Error:', error);
      return $q.reject(error); 
    });
  };

  this.countOldTestamentBooks = function(text) {
    const regex = /((Genesis|Exodus|Leviticus|Numbers|Deuteronomy|Joshua|Judges|Ruth|1 Samuel|2 Samuel|1 Kings|2 Kings|1 Chronicles|2 Chronicles|Ezra|Nehemiah|Esther|Job|Psalms|Proverbs|Ecclesiastes|Song of Solomon|Isaiah|Jeremiah|Lamentations|Ezekiel|Daniel|Hosea|Joel|Amos|Obadiah|Jonah|Micah|Nahum|Habakkuk|Zephaniah|Haggai|Zechariah|Malachi))/gi; 
    const matches = text.match(regex);

    const bookCounts = {};
    if (matches) {
      matches.forEach(book => {
        book = book.replace(/\W/g, ''); // Remove punctuation and spaces
        if (bookCounts[book]) {
          bookCounts[book]++;
        } else {
          bookCounts[book] = 1;
        }
      });
    }

    return bookCounts;
  };
});
```



