import org.apache.kafka.common.serialization.Serdes;
import org.apache.kafka.streams.*;
import org.apache.kafka.streams.kstream.*;

public class RealTimeDataPipeline {

    public static void main(String[] args) {

        // Configure Kafka Streams
        final Properties props = new Properties();
        props.put(StreamsConfig.APPLICATION_ID_CONFIG, "RealTimeDataPipeline");
        props.put(StreamsConfig.BOOTSTRAP_SERVERS_CONFIG, "localhost:9092"); 
        props.put(StreamsConfig.DEFAULT_KEY_SERDE_CLASS_CONFIG, Serdes.String().getClass());
        props.put(StreamsConfig.DEFAULT_VALUE_SERDE_CLASS_CONFIG, Serdes.String().getClass());

        // Create the Kafka Streams topology
        final StreamsBuilder builder = new StreamsBuilder();

        // Input topic:  Replace with your actual input topic name
        KStream<String, String> inputStream = builder.stream("input-topic"); 

        // Transform and process data
        inputStream
                .filter((k, v) -> v.length() > 10) // Example filter
                .mapValues(value -> value.toUpperCase()) // Example transformation
                .groupByKey();   

        // Output topics: Replace with your actual output topic names
        inputStream
                .to("transformed-data");
        inputStream
                .to("aggregated-data"); 

        // Build and start the pipeline
        final KafkaStreams streams = new KafkaStreams(builder.build(), props);
        streams.start();
    }


}
```



