using StackExchange.Redis;
using System.Threading.Tasks;

public class GameConfigService : IGameConfigService
{
    private readonly IDatabase _redisCache;
    private readonly HttpClient _httpClient;

    public GameConfigService(string redisConnectionString, string apiBaseUrl)
    {
        var connectionMultiplexer = ConnectionMultiplexer.Connect(redisConnectionString);
        _redisCache = connectionMultiplexer.GetDatabase(0); 
        _httpClient = new HttpClient();
        _httpClient.BaseAddress = new Uri(apiBaseUrl);
    }

    public async Task<GameConfiguration> GetConfigAsync(string gameId)
    {
        var cachedConfig = _redisCache.StringGet(gameId);
        if (cachedConfig.HasValue)
        {
            return JsonConvert.DeserializeObject<GameConfiguration>(cachedConfig); 
        }

        // API call with retry mechanism and exponential backoff
        try
        {
            var response = await _httpClient.GetAsync($"api/games/{gameId}");
            response.EnsureSuccessStatusCode(); // Handle errors gracefully
            var content = await response.Content.ReadAsStringAsync(); 
            var config = JsonConvert.DeserializeObject<GameConfiguration>(content);

            // Cache the retrieved configuration
            _redisCache.StringSet(gameId, JsonConvert.SerializeObject(config), TimeSpan.FromMinutes(5)); // Adjust cache expiration

            return config; 
        }
        catch (HttpRequestException ex)
        {
            // Handle transient errors with exponential backoff and retry logic
            // ...
        }

    }


}
```



