class MediaProcessor:
    def __init__(self, tool_config):
        self.tool_config = tool_config

    def process_media_files(self, input_dir, output_dir):
        if not os.path.isdir(input_dir) or not os.path.isdir(output_dir):
            logging.error("Invalid directory paths provided.")
            return 1, "Error: Invalid directory paths."

        # ... (Validate tool configuration) ... 

        jpeg_files = sorted([f for f in os.listdir(input_dir) if f.endswith('.jpg')])
        with ThreadPoolExecutor(max_workers=4) as executor:
            future_to_file = {executor.submit(self._process_file, input_path): input_path 
                             for input_path in jpeg_files}

        successes = []
        errors = []
        for future in concurrent.futures.as_completed(future_to_file):
            try:
                result = future.result()
                if result[0] == 0:
                    successes.append(result[1])
                else:
                    errors.append(result[1])
            except Exception as e:
                errors.append(f"Error processing file {future_to_file[future]}: {e}")

        summary_log = f"\nProcessed {len(jpeg_files)} JPEG files:\n" \
                      + "\n".join(successes) + "\n" \
                      + "\nErrors encountered:\n" \
                      + "\n".join(errors) 

