    $validator = new Validate(); 
    $validationResult = $validator->validate($data);
    if ($validationResult->hasErrors()) {
      return ['message' => 'error', 'errors' => $validationResult->getErrors()];
    }

    $saveAction = isset($data['sub_action']) ? $data['sub_action'] : null; 

    // Use Save method based on sub-action
    switch ($saveAction) {
      case "create":
        $saver->createAccount($data);
        break;
      case "update":
        $saver->updateAccount($data);
        break;
      case "delete":
        $saver->deleteAccount($data['id']);
        break;
      default: 
        return ['message' => 'error', 'errors' => ['Invalid sub_action']];
    }
    return ['message' => 'success'];

  } catch (Exception $e) {
    $logger->error('Error processing user account request: ' . $e->getMessage(), ['exception' => $e]); 
