// Execute command asynchronously
void execute_command(CommandInfo* info) {
  pid_t pid = fork(); 

  if (pid == 0) { // Child process
    char* args[] = {info->command, NULL};
    execvp(args[0], args);
    perror("Error executing command");
    exit(1);
  } else if (pid > 0) {
    // Parent process waits for completion
    wait(NULL);
    if (info->callback) {
      info->callback(EXIT_SUCCESS, NULL); // Pass success status and output (if needed)
    }
  } else {
    perror("Fork failed");
  }
}

// Example usage: 
