public class DynamicDatabaseManager : IDatabaseManager
{
    private readonly ConnectionManager _connectionManager;
    private readonly CachingService _cachingService;
    private readonly ErrorHandler _errorHandler;

    public DynamicDatabaseManager(IConfiguration configuration)
    {
        _connectionManager = new ConnectionManager(configuration);
        _cachingService = new CachingService();
        _errorHandler = new ErrorHandler(logger, metricsProvider); 
    }

    public async Task<T> ExecuteQueryAsync<T>(string query, object parameters = null)
    {
        var connection = await _connectionManager.GetConnectionAsync();

        try
        {
            using (var command = new SqlCommand(query, connection))
            {
                if (parameters != null)
                {
                    command.Parameters.AddAddWithValue("@parameters", parameters); // Adapt parameter handling as needed
                }
                var result = await command.ExecuteScalarAsync();
                return (T)result; // Cast result to desired type
            }
        }
        catch (Exception ex)
        {
            _errorHandler.HandleError(ex, query, parameters);
            throw; 
        }
        finally
        {
            connection.Dispose();
        }
    }

    // Add other methods for database operations like ExecuteNonQueryAsync, ExecuteReaderAsync, etc.

    // Example Configuration:
    public class ConnectionManagerConfiguration
    {
        public List<ConnectionString> Connections { get; set; } = new List<ConnectionString>(); 
    }

    public class ConnectionString
    {
        public string Name { get; set; }
        public string Server { get; set; }
        // Add other connection properties
    }


}
