# JSONIntegration/api_connector.py
from aiohttp import ClientSession
import asyncio
from typing import Callable, Dict


class APIConnector:
    async def __init__(self):
        self.session = ClientSession()
        self.connection_state = "closed"  

    async def _handle_request(self, method: str, url: str, params: Dict = None) -> dict:
        try:
            async with self.session.request(method, url, params=params) as response:
                if response.status == 200:
                    return await response.json()
                else:
                    raise Exception(f"API request failed with status code {response.status}")
        except Exception as e:
            self.connection_state = "error"
            raise e

    async def fetch_data(self, url: str, params: Dict = None) -> dict:
        # Implement exponential backoff retry logic here 
        return await self._handle_request("GET", url, params)

    async def push_data(self, url: str, data: dict):
        # Implement exponential backoff retry logic here
        return await self._handle_request("POST", url, json=data)

```



