#include <iostream>
#include <thread>
#include <queue>
#include <mutex>
#include <condition_variable>

class EventBus {
public:
    void ingestEvent(const std::string& event) {
        std::unique_lock<std::mutex> lock(eventQueueMutex_);
        eventQueue_.push(event);
        conditionVariable_.notify_one(); 
    }

    void processEvents() {
        while (true) {
            std::unique_lock<std::mutex> lock(eventQueueMutex_);
            conditionVariable_.wait(lock, [this](){ return !eventQueue_.empty(); });
            const std::string& event = eventQueue_.front();
            eventQueue_.pop();
            lock.unlock();

            // Process the event here
            std::cout << "Processing event: " << event << std::endl;
        }
    }

private:
    std::queue<std::string> eventQueue_;
    std::mutex eventQueueMutex_;
    std::condition_variable conditionVariable_;
};

int main() {
    EventBus bus;
    std::thread ingestionThread([&bus]() { 
        // Simulate ingesting events from the distributed bus
        for (int i = 0; i < 100; ++i) {
            bus.ingestEvent("Event " + std::to_string(i));
            std::this_thread::sleep_for(std::chrono::milliseconds(100));
        }
    });

    std::thread processingThread([&bus]() { bus.processEvents(); });

    ingestionThread.join();
    processingThread.join();

    return 0;
}   
