// Simple mock implementation for testing
class MockMD5Api : public MD5Api {
public:
    std::string computeHash(const std::string& input) override {
        // Simulate potential failures or latency here
        if (rand() % 2 == 0) {
            throw std::runtime_error("Mock API Error"); 
        }
        return "mocked_hash_" + input;
    }
};

// Thread-safe forward list wrapper with logging
class SafeForwardList {
public:
    std::forward_list<std::string> data;
    mutable std::mutex mutex;

    void insertOrAppendWithHash(const std::string& target, const std::string& dataStr, MD5Api* api) {
        std::lock_guard<std::mutex> lock(mutex); 
        auto it = data.before_begin();
        for (auto node = data.begin(); node != data.end(); ++node) {
            if (*node == target) {
                it = node;
            }
        }
        // Replace or append based on target existence
        std::string hashValue = "";
        try {
            hashValue = api->computeHash(dataStr); 
        } catch (const std::exception& e) {
            std::cerr << "Error computing hash: " << e.what() << std::endl;
        }

        if (it != data.before_begin()) { // Target found, replace and append
            data.insert_after(it, hashValue);
            data.insert_after(it, dataStr);
        } else { // Target not found, append to end
            data.push_back(hashValue); 
            data.push_back(dataStr);
        }

        // Log the operation
        std::cout << "Operation completed: ";
        if (it != data.before_begin()) {
            std::cout << "Replaced '" << target << "' with hash '" << hashValue << "' and data '" << dataStr << "'" << std::endl; 
        } else {
            std::cout << "Appended '" << hashValue << "' and '" << dataStr << "'" << std::endl; 
        }

    }
};


