    MockMD5Api mockApi;

    // Create a safe forward list
    SafeForwardList list;

    // Populate the list with some initial data
    list.data = {"apple", "banana"}; 

    // Test insertOrAppendWithHash function
    list.insertOrAppendWithHash("banana", "new_data", &mockApi); 

    return 0;
}
