// Cache abstraction layer
public interface ICache
{
    Task<FinancialData> GetAsync(string symbol);
    Task SetAsync(string symbol, FinancialData data, TimeSpan expiration);
    Task InvalidateAsync(string symbol); 
}

// Redis cache implementation (or other distributed caching technology)
// ...

// Service responsible for ingesting and processing data
public class MarketDataService : IMarketDataService
{
    private readonly IDataProvider _dataProvider;
    private readonly ICache _cache;
    private readonly IConfiguration _configuration;

    public MarketDataService(IDataProvider dataProvider, ICache cache, IConfiguration configuration)
    {
        _dataProvider = dataProvider;
        _cache = cache;
        _configuration = configuration;
    }

    public async Task<FinancialData> GetMarketDataAsync(string symbol)
    {
        if (_cache.GetAsync(symbol).Result != null)
        { 
            return await _cache.GetAsync(symbol); 
        }

        // Handle cache misses: fetch data from provider, cache it, and return
        FinancialData data = await _dataProvider.GetDataAsync(symbol);
        await _cache.SetAsync(symbol, data, _configuration.GetCacheExpiration(symbol)); // Use config for expiration
