@app.route('/trends', methods=['GET'])
def get_trends():
    try:
        language = request.args.get('language')
        region = request.args.get('region')

        if language and region:
            posts = cache.get((language, region))
            if not posts:
                # Fetch data from APIs if not cached
                posts = fetch_posts(api_clients[language], language, region)
