class DynamicScriptLoader {
  constructor(config) {
    this.config = config;
    this.scriptCache = {}; 
    this.retryAttempts = {}; // Track retry attempts for each script URL
  }

  async loadAndExecuteScripts() {
    const executionOrder = this.config.order;
    for (const scriptUrl of executionOrder) {
      await this.loadAndExecuteScript(scriptUrl);
    }
  }

  async loadAndExecuteScript(scriptUrl) {
    if (this.scriptCache[scriptUrl]) {
      console.log(`Loaded from cache: ${scriptUrl}`);
      return new Promise((resolve) => resolve()); // Resolve immediately if cached
    }

    const startTime = Date.now();

    try {
      const response = await this.fetchScript(scriptUrl);
      this.scriptCache[scriptUrl] = response;
      console.log(`Loaded script: ${scriptUrl}, time: ${(Date.now() - startTime) / 1000}s`);

      const scriptElement = document.createElement('script');
      scriptElement.src = scriptUrl;
      scriptElement.onload = () => { 
        console.log(`Executed script: ${scriptUrl}`); // Log execution completion
      };
      document.head.appendChild(scriptElement);

    } catch (error) {
      console.error(`Failed to load script: ${scriptUrl}, retrying...`);
      if (this.retryAttempts[scriptUrl] < 3) {
        // Exponential backoff with maximum attempts
        const delay = Math.pow(2, this.retryAttempts[scriptUrl]) * 1000; 
        setTimeout(() => {
          this.loadAndExecuteScript(scriptUrl); // Retry after delay
          this.retryAttempts[scriptUrl]++;
        }, delay);
      } else {
        // Fallback mechanism (optional) - log error, use default behavior, etc.
        console.error(`Failed to load script after retries: ${scriptUrl}`); 
      }
    } 
  }

  fetchScript(url) {
    // Handle API calls with rate limits and potential caching
  }

}



