    fn new(sources: Vec<Box<dyn DataSource>>, processors: Vec<Box<dyn Processor>>, storage: Arc<Mutex<Database>>) -> Self {
        DataProcessor { sources, processors, storage }
    }

    async fn process_data(&self) {
        for source in &self.sources {
            let data = source.fetch_data().await;
            if let Ok(data) = data {
                for processor in &self.processors {
                    processor.process(data).await;
                }
                self.storage.lock().unwrap().store(&data).await; 
            } else {
                // Handle error gracefully
            }
        }
    }
}

