    {
        _config = config;
        _httpClientFactory = httpClientFactory;
    }

    public async Task Run()
    {
        var apiEndpoints = _config.GetSection("ApiEndpoints").Get<List<ApiEndpoint>>(); 

        foreach (var endpoint in apiEndpoints)
        {
            // Initialize Polly policy for circuit breaking and retry
            var policy = Policy
                .Handle<Exception>()
                .WaitAndRetryAsync(new[] { TimeSpan.FromSeconds(5), TimeSpan.FromMinutes(1) });  

            await policy.ExecuteAsync(async () => 
            {
                // Use HttpClientFactory to get a configured client for this API
                var client = _httpClientFactory.CreateClient($"Api_{endpoint.Name}"); 

                // Make the request, handle encryption and decryption
                var response = await client.GetAsync(endpoint.Url);

                // ... Validate response, decrypt data, log results

            });
        }
    }
}



public class ApiEndpoint
{
