    private readonly string _configFile;
    private readonly object _lock = new object();
    private XmlDocument _configDoc;

    public ConfigService(string configFile)
    {
        _configFile = configFile;
        LoadConfig();
    }

    public string GetHash(string input)
    {
        using (var md5 = MD5.Create())
        {
            byte[] hashBytes = md5.ComputeHash(Encoding.UTF8.GetBytes(input));
            return BitConverter.ToString(hashBytes).Replace("-", "").ToLower();
        }
    }

    public string GetConfigValue(string elementName, string defaultValue = "")
    {
        lock (_lock)
        {
            if (_configDoc == null) 
            {
                Console.WriteLine("Warning: Configuration file is missing or invalid.");
                return defaultValue;
            }

            XmlNode node = _configDoc.SelectSingleNode($"/{elementName}");
            if (node != null)
            {
                return node.InnerText;
            }
            else
            {
                Console.WriteLine($"Warning: No '{elementName}' element found in the configuration file.");
                return defaultValue;
            }
        }
    }

    private void LoadConfig()
    {
        try
        {
            _configDoc = new XmlDocument();
            _configDoc.Load(_configFile);
        }
        catch (Exception ex)
        {
            Console.WriteLine($"Error loading configuration file: {ex.Message}");
            _configDoc = null;
        }
    }
}


