import threading
import json

class ConfigManager:
    def __init__(self):
        self.registries = {} 
        self.lock = threading.RLock()
        self.external_service = ExternalConfigService()  

    def register_factory(self, registry_name, factory_func):
        with self.lock:
            if registry_name not in self.registries:
                self.registries[registry_name] = []
            self.registries[registry_name].append(factory_func)

    def get_factory(self, config_type, registry_name="production"):
        with self.lock:
            if registry_name in self.registries:
                for factory_func in self.registries[registry_name]:
                    if factory_func.config_type == config_type:
                        return factory_func
            return None

    def load_config(self, config_path):
        with open(config_path, "r") as f:
            config_data = json.load(f)
        factory = self.get_factory(config_data["type"])
        if factory:
            return factory.load_from_json(config_data)

