// Placeholder classes for API and cache interactions
class RestApi {
public:
    virtual bool validateString(const std::string& str) = 0;
};

class DistributedCache {
public:
    virtual bool getValidationStatus(const std::string& str) = 0;
    virtual void setValidationStatus(const std::string& str, bool isValid) = 0;
};

class DynamicStringList {
private:
    std::forward_list<std::unique_ptr<std::string>> strings;
    std::mutex mutex;
    RestApi* api;
    DistributedCache* cache;

public:
    DynamicStringList(RestApi* api, DistributedCache* cache) : api(api), cache(cache) {}

    void addString(const std::string& str) {
        std::lock_guard<std::mutex> lock(mutex);

        // Cache validation check
        if (cache->getValidationStatus(str)) {
            strings.push_front(std::make_unique<std::string>(str));
            log("String added:", *strings.front()); 
            return;
        }

        // API validation with retries and exponential backoff
        bool isValid = false;
        int retryCount = 0;
        while (!isValid && retryCount < 3) {
            if (api->validateString(str)) {
                isValid = true;
            } else {
                std::this_thread::sleep_for(std::chrono::milliseconds(1 << retryCount));
                retryCount++;
            }
        }

        if (isValid) {
            cache->setValidationStatus(str, true); // Cache result
            strings.push_front(std::make_unique<std::string>(str));
            log("String added:", *strings.front()); 
        } else {
            // Handle API validation failure
            log("String rejected: ", str); 
        }
    }

private:
    void log(const std::string& message, const std::string& str) {
        std::cout << "DynamicStringList: " << message << str << std::endl;
    }
};




