class Scheduler:
    def __init__(self, max_concurrency):
        self.max_concurrency = max_concurrency
        self.queue = []

    def schedule_task(self, task, callback):
        self.queue.append((task, callback))
        if len(self.queue) <= self.max_concurrency:
            self._run_tasks()

    def _run_tasks(self):
        while True:
            if len(self.queue) > 0:
                task, callback = self.queue.pop(0)
                callback(task)
            else:
                break  # Wait for more tasks


