    pthread_mutex_init(&pool->mutex, NULL); 
    pool->num_sessions = 0;
    return pool;
}

int add_session(SessionPool *pool, int session_id, char *user_data) {
    pthread_mutex_lock(&pool->mutex);
    if (pool->num_sessions < sizeof(pool->sessions) / sizeof(pool->sessions[0])) { 
        pool->sessions[pool->num_sessions++] = malloc(sizeof(SessionContext));
        pool->sessions[pool->num_sessions - 1]->session_id = session_id;
        pool->sessions[pool->num_sessions - 1]->user_data = strdup(user_data);
    } else {
        // Handle pool overflow (e.g., log error, reject session)
    }
    pthread_mutex_unlock(&pool->mutex);
    return 0; // Indicate success
}

