#include <string.h>
#include <stdlib.h>
#include <pthread.h>

typedef struct {
  size_t max_length;
  pthread_mutex_t mutex;
} ConditionalStringAppenderConfig;

char* ConditionalStringAppender(ConditionalStringAppenderConfig* config, const char* input) {
  pthread_mutex_lock(&config->mutex);
  size_t length = strlen(input);
  if (length <= config->max_length) {
    char* output = malloc(length + 2);
    strcpy(output, input);
    output[length] = '/';
    output[length + 1] = '\0';
    pthread_mutex_unlock(&config->mutex);
    return output;
  } else {
    pthread_mutex_unlock(&config->mutex);
    return NULL;
  }
}
