#include <pthread.h>
#include <stdlib.h>
#include <string.h>

// Define packet metadata structure
typedef struct {
  char source_ip[32];
  char destination_ip[32];
  int protocol;
  size_t size;
} PacketMetadata;

// Define a global mutex for concurrent access
pthread_mutex_t packet_mutex = PTHREAD_MUTEX_INITIALIZER;

// Define an array to store packet metadata entries
PacketMetadata *packets = NULL;
size_t packet_count = 0;
size_t max_packet_count = 0;

// Function to add a new packet entry
void add_packet(const char *source_ip, const char *destination_ip, int protocol, size_t size) {
  pthread_mutex_lock(&packet_mutex);
  if (packet_count == max_packet_count) {
    max_packet_count *= 2;
    packets = realloc(packets, max_packet_count * sizeof(PacketMetadata));
    if (!packets) {
      // Handle memory allocation failure
      fprintf(stderr, "Error: Memory allocation failed\n");
      pthread_mutex_unlock(&packet_mutex);
      return;
    }
  }
  strcpy(packets[packet_count].source_ip, source_ip);
  strcpy(packets[packet_count].destination_ip, destination_ip);
  packets[packet_count].protocol = protocol;
  packets[packet_count].size = size;
  packet_count++;
  pthread_mutex_unlock(&packet_mutex);
}

// Function to update an existing packet entry
void update_packet(size_t index, const char *source_ip, const char *destination_ip, int protocol, size_t size) {
  pthread_mutex_lock(&packet_mutex);
  if (index >= packet_count) {
    // Handle invalid index
    fprintf(stderr, "Error: Invalid packet index\n");
    pthread_mutex_unlock(&packet_mutex);
    return;
  }
  strcpy(packets[index].source_ip, source_ip);
  strcpy(packets[index].destination_ip, destination_ip);
  packets[index].protocol = protocol;
  packets[index].size = size;
  pthread_mutex_unlock(&packet_mutex);
}

// Function to remove a packet entry by index
void remove_packet(size_t index) {
  pthread_mutex_lock(&packet_mutex);
  if (index >= packet_count) {
    // Handle invalid index
    fprintf(stderr, "Error: Invalid packet index\n");
    pthread_mutex_unlock(&packet_mutex);
    return;
  }
  for (size_t i = index; i < packet_count - 1; i++) {
    packets[i] = packets[i + 1];
  }
  packet_count--;
  pthread_mutex_unlock(&packet_mutex);
}

// Function to iterate through packets and compute total size
size_t get_total_packet_size() {
  size_t total_size = 0;
  pthread_mutex_lock(&packet_mutex);
  for (size_t i = 0; i < packet_count; i++) {
    total_size += packets[i].size;
  }
  pthread_mutex_unlock(&packet_mutex);
  return total_size;
}

