#include <forward_list>
#include <string>

void insertAfterFirstOccurrence(std::forward_list<std::string>& list, const std::string& target, const std::string& insert) {
  auto before = list.before_begin();
  for (auto it = list.begin(); it != list.end(); ++it) {
    if (*it == target) {
      list.insert_after(it, insert);
      return;
    } 
    before = it;
  }
  list.insert_after(before, insert);
}
