class DOMManager {
  constructor(apiEndpoint) {
    this.apiEndpoint = apiEndpoint;
    this.nodes = {}; 
    this.websocketConnection = null; // Initialize WebSocket connection later
    this.throttleCounter = 0; // Throttle API requests
    this.lastRequestTime = Date.now();

  }

  async fetchNodeMetadata(nodeId) { 
    // Check throttling limits and make API request if within limits
    const currentTime = Date.now();
    if (currentTime - this.lastRequestTime < 500 && this.throttleCounter >= 3) {
      console.warn("API Throttled: Waiting for cooldown period");
      return; 
    }

    this.throttleCounter++;
    this.lastRequestTime = currentTime;

    try {
      const response = await fetch(`${this.apiEndpoint}/nodes/${nodeId}`);
      if (!response.ok) throw new Error(`API Error: ${response.status}`);
      return await response.json(); 
    } catch (error) {
      console.error("Error fetching node metadata:", error);
      // Implement fallback mechanism here (e.g., local database)
      return null; // Return placeholder data if necessary
