# Python Audit Report Generator Script

import json

def generate_audit_report(transactions):
    """
    Generates a standardized audit report from a list of JSON-encoded transaction objects.

    Args:
        transactions (list): A list of JSON-encoded transaction objects.

    Returns:
        str: A formatted audit report string.
    """
    report = "Transaction Audit Report:\n"
    for transaction in transactions:
        timestamp = transaction['timestamp']
        amount = transaction['amount']
        transaction_id = transaction['transaction_id']
        report += f"Timestamp: {timestamp}, Amount: {amount}, Transaction ID: {transaction_id}\n"

    return report

# Example Usage
transactions = [
    {'timestamp': '2023-10-26 10:00:00', 'amount': 100.00, 'transaction_id': 'TXN-123'},
    {'timestamp': '2023-10-26 10:05:00', 'amount': 50.50, 'transaction_id': 'TXN-456'},
]
audit_report = generate_audit_report(transactions)
print(audit_report)
