        // 2. Data Ingestion from Kafka
        kafkaConsumer.subscribe(Arrays.asList("your-data-topic")); 
        for (ConsumerRecords<String, String> records : kafkaConsumer) {
            for (ConsumerRecord<String, String> record : records) {
                // Process incoming data from Kafka

                // 3. Data Transformation & Processing (Spark Example)
                SparkSession spark = SparkSession.builder().appName("DataPipeline").getOrCreate();
                Dataset<Row> data = spark.read().json(record.value());
                data.transform(...)  // Apply your transformations here
                    .write()
                    .parquet("path/to/transformed_data");

                // 4. Data Loading to Cloud Storage
                BlobInfo blobInfo = BlobInfo.newBuilder(bucketInfo.getName(), "transformed_data").build();
                storageOptions.getService().create(blobInfo, data); 

