      ++it;
    }

    // If target is found, insert hashed data after the last occurrence.
    if (it != forwardList_.end()) {
      forwardList_.insert(it, hashedData);
    } 
    // Otherwise, append hashed data to the end of the list.
    else {
      forwardList_.push_back(hashedData);
    }

    processing_ = false;
    cv_.notify_all(); 
