char* ConditionalStringAppender(const char* input, size_t size_limit) {
  size_t input_length = strlen(input);
  if (input_length <= size_limit) {
    char* new_string = malloc(input_length + 2); // Allocate space for the string and the '/'
    strcpy(new_string, input);
    new_string[input_length] = '/';
    new_string[input_length + 1] = '\0';
    return new_string;
  } else {
    return NULL;
  }
}
