using System;
using System.Xml;
using System.XPath;

public class XmlParser
{
    public static T ParseXmlElement<T>(string xml, string xpathExpression) where T : class
    {
        var doc = new XmlDocument();
        doc.LoadXml(xml);
        var navigator = doc.CreateNavigator();
        var result = navigator.SelectSingleNode(xpathExpression);

        if (result == null)
        {
            throw new Exception($"No element found matching XPath: {xpathExpression}");
        }
        else if (navigator.GetNodesByXPath(xpathExpression).Count > 1)
        {
            throw new Exception($"Multiple elements found matching XPath: {xpathExpression}");
        }

        return result?.CastToType<T>();
    }
}
