#include <thread>
#include <queue>
#include <mutex>
#include <condition_variable>

struct Transaction {
  int id;
  double amount;
};

class TransactionProcessor {
public:
  void processTransaction(const Transaction& transaction) {
    std::unique_lock<std::mutex> lock(mutex_);
    transactionQueue_.push(transaction);
    cv_.notify_one();
  }

  void run() {
    std::thread t([this]() { 
      while (true) {
        std::unique_lock<std::mutex> lock(mutex_);
        cv_.wait(lock, [this](){ return !transactionQueue_.empty(); });
        Transaction transaction = transactionQueue_.front();
        transactionQueue_.pop();

        // Process transaction here 
        // ...

      }
    });
  }

private:
  std::queue<Transaction> transactionQueue_;
  std::mutex mutex_;
  std::condition_variable cv_;
};
