# Python Script for Generating Transaction Reports
import json
import datetime

def generate_report(transactions, start_date=None, end_date=None):
  filtered_transactions = transactions
  if start_date:
    filtered_transactions = [t for t in transactions if datetime.datetime.strptime(t['timestamp'], '%Y-%m-%d %H:%M:%S') >= start_date]

  if end_date:
    filtered_transactions = [t for t in transactions if datetime.datetime.strptime(t['timestamp'], '%Y-%m-%d %H:%M:%S') <= end_date]

  report_data = {
      'transactions': filtered_transactions,
      'start_date': start_date,
      'end_date': end_date
  }
  return json.dumps(report_data, indent=2)


# ... (Usage Example)
