// This is a simplified representation and would require significant expansion 
// for a production-ready system.

use tokio::{sync::mpsc, runtime::Runtime};
use std::collections::HashMap;
use serde::{Deserialize, Serialize};

#[derive(Serialize, Deserialize, Debug)]
struct State {
    value: String,
}

struct FSM<T> {
    current_state: T,
    transitions: HashMap<(T, &str), (T, fn(&State) -> Result<(), Box<dyn std::error::Error>>)>,
}

impl<T> FSM<T> {
    fn new(initial_state: T) -> Self {
        Self {
            current_state: initial_state,
            transitions: HashMap::new(),
        }
    }

    async fn handle_event(&mut self, event: &str) -> Result<(), Box<dyn std::error::Error>> {
        match self.transitions.get(&(self.current_state, event)) {
            Some((next_state, transition_fn)) => {
                let state = State { value: "Updated state".to_string() };
                transition_fn(&state)?;
                self.current_state = *next_state;
                Ok(())
            }
            None => Err("Invalid event".into()),
        }
    }

    fn add_transition(mut self, from_state: T, event: &str, to_state: T, transition_fn: fn(&State) -> Result<(), Box<dyn std::error::Error>>) -> Self {
        self.transitions.insert((from_state, event), (to_state, transition_fn));
        self
    }
}

#[tokio::main]
async fn main() {
    let rt = Runtime::new().unwrap();

    // Create an instance of the FSM
    let mut fsm = FSM::<String>::new("Initial".to_string())
        .add_transition(
            "Initial".to_string(),
            "Event1".to_string(),
            "State1".to_string(),
            |state: &State| {
                // Handle event and update state
                println!("Transitioning to State1, {}", state.value);
                Ok(())
            },
        )
        .add_transition(
            "State1".to_string(),
            "Event2".to_string(),
            "Final".to_string(),
            |state: &State| {
                println!("Transitioning to Final, {}", state.value);
                Ok(())
            },
        );

    // Process events asynchronously
    let (tx, rx) = mpsc::channel(1024);
    rt.spawn(async move {
        while let Ok(event) = rx.recv().await {
            match fsm.handle_event(&event).await {
                Ok(_) => println!("Event handled successfully"),
                Err(e) => eprintln!("Error handling event: {}", e),
            }
        }
    });

    // Send events to the FSM
    tx.send("Event1").await.unwrap();
    tx.send("Event2").await.unwrap();


    rt.shutdown_timeout(std::time::Duration::from_secs(5)).await;
}
```



