                case 'active':
                    $this->processSubscriptionActivation($user_id, $subscriptionPlan);
                    break;
                case 'canceled':
                    $this->processSubscriptionCancellation($user_id, $request->getCancelReason());
                    break;
                // ... other status cases
            }

            // Generate success response with updated subscription details
