                await _contentService.UpdateContentAsync(request, version, id);
                return Ok();
            }
            catch (Exception ex)
            {
                return StatusCode(500, $"Error updating content: {ex.Message}");
            }
        }

        [HttpDelete("{version}/{id}")]
        public async Task<IActionResult> DeleteContent(string version, int id)
        {
            try
            {
                await _contentService.DeleteContentAsync(version, id);
                return Ok();
            }
            catch (Exception ex)
            {
                return StatusCode(500, $"Error deleting content: {ex.Message}");
            }
        }

        // ... other API endpoints for retrieving content, version management, etc.
    }
