// copyBytesFromChunks.js
function copyBytesFromChunks(byteCount, buffers) {
  const newBuffer = Buffer.alloc(byteCount);
  let offset = 0;
  for (const buffer of buffers) {
    const len = Math.min(buffer.length, byteCount - offset);
    buffer.copy(newBuffer, offset, 0, len);
    offset += len;
  }
  return newBuffer;
}

