    @PostMapping("/authenticate")
    public ResponseEntity<TokenResponse> authenticate(@RequestBody LoginRequest loginRequest) {
        // 1. Validate User Credentials (Against External Provider)
        String username = loginRequest.getUsername();
        String password = loginRequest.getPassword();
        AuthenticationResult authResult = externalAuthProvider.authenticateUser(username, password);

        if (!authResult.isAuthenticated()) {
            return new ResponseEntity<>(HttpStatus.UNAUTHORIZED); // Handle Invalid Credentials
        }

        // 2. Generate JWT Token
        String token = generateJwtToken(authResult.getUserId(), jwtConfig.getSecret());

        return new ResponseEntity<>(new TokenResponse(token), HttpStatus.OK); 
    }


