["```rust
fn copy_bytes(data_chunks: &[&[u8]], byte_count: usize) -> Vec<u8> {
    let mut buffer = Buffer::allocUnsafe(byte_count);
    let mut bytes_copied = 0;

    for chunk in data_chunks {
        if bytes_copied >= byte_count {
            break;
        }
        let chunk_len = chunk.len();
        let copy_len = std::cmp::min(byte_count - bytes_copied, chunk_len);
        buffer[bytes_copied..bytes_copied + copy_len].copy_from_slice(&chunk[..copy_len]);
        bytes_copied += copy_len;
    }

    buffer 
}
```




