public class ActivityProcessor extends SimpleChannelInboundHandler<ActivityEvent> {

    private final EventDispatcher dispatcher;

    public ActivityProcessor(EventDispatcher dispatcher) {
        this.dispatcher = dispatcher;
    }

    @Override
    protected void channelRead0(ChannelHandlerContext ctx, ActivityEvent msg) throws Exception {
        // Dispatch event to appropriate processor based on type
        dispatcher.dispatch(msg); 
    }
}


interface EventDispatcher {
    void dispatch(ActivityEvent event);
}

class DefaultEventDispatcher implements EventDispatcher {

    private final Map<String, ActivityProcessor> processors = new HashMap<>();

    public void registerProcessor(String eventType, ActivityProcessor processor) {
        processors.put(eventType, processor);
    }

    @Override
    public void dispatch(ActivityEvent event) {
        ActivityProcessor processor = processors.get(event.getType());
        if (processor != null) {
            processor.process(event);
        } else {
            // Handle unknown event type
        }
    }
}

abstract class ActivityProcessor {
    protected abstract void process(ActivityEvent event); 
}


