public class DataLoadingService : IDataLoadingService
{
    private readonly ILogger<DataLoadingService> _logger;
    private readonly IBinaryFileReader _binaryFileReader;
    private readonly IRESTApiClient _restApiClient;
    private readonly ICacheProvider _cacheProvider;
    private readonly SchemaValidator<TDataItem> _schemaValidator;

    public DataLoadingService(ILogger<DataLoadingService> logger, 
                            IBinaryFileReader binaryFileReader, 
                            IRESTApiClient restApiClient, 
                            ICacheProvider cacheProvider,
                            SchemaValidator<TDataItem> schemaValidator)
    {
        _logger = logger;
        _binaryFileReader = binaryFileReader;
        _restApiClient = restApiClient;
        _cacheProvider = cacheProvider;
        _schemaValidator = schemaValidator;
    }

    public async Task<IEnumerable<DeserializedData>> LoadAndEnrichDataAsync(string filePath)
    {
        var deserializedItems = await _binaryFileReader.ReadAsync<TDataItem>(filePath);

        // Validate each item against the schema
        foreach (var item in deserializedItems)
        {
            _schemaValidator.Validate(item); 
        }

        // Enrich data with metadata from the API and cache results
        var enrichedData = await Task.WhenAll(deserializedItems.Select(async item =>
        {
            var cachedResult = _cacheProvider.Get(item.Id);
            if (cachedResult != null)
            {
                return cachedResult; 
            }

            var metadata = await _restApiClient.GetMetadataAsync(item.Id);
            _cacheProvider.Add(item.Id, metadata); // Cache the result

            // Combine item and metadata 
            return new DeserializedData { DataItem = item, Metadata = metadata };
        }));

        return enrichedData;
    }
}
