// ... (Code for Redis interaction, Tokio runtime setup, Kubernetes orchestration)

async fn copy_bytes(data_chunks: &[Vec<u8>], start_offset: usize, num_bytes: usize) -> Result<Vec<u8>, std::io::Error> {
    let mut buffer = Vec::with_capacity(num_bytes);
    buffer.allocUnsafe();

    let mut bytes_copied = 0;
    for chunk in data_chunks {
        if bytes_copied >= num_bytes {
            break;
        }
        let chunk_len = chunk.len();
        let copy_len = std::cmp::min(num_bytes - bytes_copied, chunk_len);
        buffer[bytes_copied..bytes_copied + copy_len].copy_from_slice(&chunk[..copy_len]);
        bytes_copied += copy_len;
    }

    Ok(buffer)
}


