def copy_bytes(data_chunks, start_index, length):
    new_buffer = Buffer.allocUnsafe(length); 
    for i in range(len(data_chunks)):
        data_chunk = data_chunks[i];
        if (start_index < len(data_chunk)):
            end_index = min(start_index + length, len(data_chunk));
            data_chunk.copy(new_buffer, start_index);
            start_index = end_index;

    return new_buffer
