# logging_framework.py

import logging
from abc import ABC, abstractmethod
from threading import Lock

class Logger(ABC):
    @abstractmethod
    def log(self, level, message):
        pass

    @abstractmethod
    def flush(self):
        pass

class FileLogger(Logger):
    def __init__(self, filename, level="INFO"):
        self.logger = logging.getLogger("FileLogger")
        self.logger.setLevel(level)
        handler = logging.FileHandler(filename)
        formatter = logging.Formatter("%(asctime)s - %(levelname)s - %(message)s")
        handler.setFormatter(formatter)
        self.logger.addHandler(handler)

    def log(self, level, message):
        self.logger.log(level, message)

    def flush(self):
        pass  

class DatabaseLogger(Logger):
    # ... Implementation for database logging ...

class CloudLogger(Logger):
    # ... Implementation for cloud logging (e.g., AWS CloudWatch) ...


class LogManager:
    __instance = None
    _loggers = {}
    _lock = Lock() 

    def __new__(cls):
        if cls.__instance is None:
            cls.__instance = super(LogManager, cls).__new__(cls)
        return cls.__instance

    def register_logger(self, name, logger_type, **kwargs):
        with self._lock:
            if name in self._loggers:
                raise ValueError(f"Logger with name '{name}' already exists.")
            self._loggers[name] = {
                'type': logger_type,
                'config': kwargs 
            }

    def get_logger(self, name):
        with self._lock:
            return self._loggers[name]['type'](**self._loggers[name]['config'])



# Example Usage:
manager = LogManager()
manager.register_logger("file", FileLogger, filename="app.log")
manager.register_logger("database", DatabaseLogger)

file_logger = manager.get_logger("file")
file_logger.log(logging.INFO, "This is an informational message.")

# ... Add more logging configurations as needed



