// Function to add a new command task
void add_command_task(char *command, int priority) {
  // Allocate memory for the task
  CommandTask *new_task = malloc(sizeof(CommandTask)); 
  if (new_task == NULL) {
    log_error("Memory allocation failed"); 
    return;
  }

  // Set command and priority
  new_task->command = strdup(command);
  new_task->priority = priority;

  // Add the task to the queue
  tasks[num_tasks] = *new_task;
  num_tasks++;
}

int main() {
  // Initialize logging, authentication, and plugin system

  // Main loop to process command tasks
  while (1) { 
    for (int i = 0; i < num_tasks; i++) {
      if (tasks[i].priority > 0) {
        execute_command(&tasks[i]);
      }
    }
    // Sleep to avoid busy-waiting
  }

  return 0;
}
