from schemaregistry.client import SchemaRegistryClient

class DataProcessor:
    def __init__(self, broker_url, registry_url):
        self.broker_url = broker_url
        self.registry_url = registry_url
        self.source_connectors = {} # Store connectors for different data sources
        self.processors = [] # List of processing functions
        self.sink_connectors = [] # List of connectors for output sinks

    def add_source(self, source_type, config):
        connector = SourceConnectorFactory.create_connector(source_type, self.registry_url, config)
        self.source_connectors[source_type] = connector

    def add_processor(self, processor_func):
        self.processors.append(processor_func)

    def add_sink(self, sink_type, config):
        connector = SinkConnectorFactory.create_connector(sink_type, self.broker_url, config)
        self.sink_connectors.append(connector)


    def process_data(self):
        for source_type in self.source_connectors:
            source_connector = self.source_connectors[source_type]
            while True:
                data = source_connector.read_data()  
                if data is None:
                    break 
                for processor in self.processors:
                    data = processor(data)
                for sink in self.sink_connectors:
                    sink.write_data(data)

class SourceConnectorFactory:
    @staticmethod
    def create_connector(source_type, registry_url, config):
        if source_type == "JSON":
            return JsonSourceConnector(registry_url, config)
        elif source_type == "CSV":
            return CsvSourceConnector(config)
        elif source_type == "Avro":
            return AvroSourceConnector(registry_url, config)

class SinkConnectorFactory:
    @staticmethod
    def create_connector(sink_type, broker_url, config):
        if sink_type == "Kafka":
            return KafkaSinkConnector(broker_url, config)



