    {
        var cachedConfig = _redisCache.GetOrCreateAsync<GameEngineConfiguration>(gameId, async () =>
        {
            // 1. Handle API Call with Retry Mechanism and Exponential Backoff
            try
            {
                var response = await _httpClient.GetAsync($"https://api.example.com/games/{gameId}/config");
