import org.apache.kafka.clients.producer.*;

public class UserActivityLogMicroservice {

    private static final String KAFKA_TOPIC = "user-activity";

    public static void main(String[] args) {
        // Configure Kafka producer
        ProducerConfig config = new ProducerConfig();
        Producer<String, String> producer = new KafkaProducer<>(config);

        // Log ingestion loop
        while (true) {
            // Simulate user activity data
            String userId = "user123";
            String activity = "viewed_product";

            // Create log entry message
            String message = String.format("{\"userId\":\"%s\", \"activity\":\"%s\"}", userId, activity);

            // Send log entry to Kafka topic
            producer.send(new ProducerRecord<>(KAFKA_TOPIC, message), new Callback() {
                @Override
                public void onCompletion(RecordMetadata metadata, Exception exception) {
                    if (exception != null) {
                        System.err.println("Error sending log entry: " + exception.getMessage());
                    } else {
                        System.out.println("Log entry sent successfully to Kafka topic: " + metadata.topic() + " with partition: " + metadata.partition());
                    }
                }
            });

            // Simulate processing delay
            try {
                Thread.sleep(100);
            } catch (InterruptedException e) {
                e.printStackTrace();
            }
        }
    }
}
