    public SecureHashingLibrary(IConfigService configService, ILogger logger, IExternalApiService externalApiService)
    {
        _configService = configService;
        _logger = logger;
        _externalApiService = externalApiService;
    }

    // Method to hash user input string
    public string HashString(string inputString)
    {
        var hashingAlgorithm = _configService.GetHashingAlgorithm(); // Dynamically load algorithm based on config
        using (var sha256 = new SHA256Managed()) 
        {
            byte[] hashBytes = sha256.ComputeHash(Encoding.UTF8.GetBytes(inputString));
            return Convert.ToBase64String(hashBytes); // Encode hash for storage/transmission
        }
    }

    // Method to verify hashed string against original input 
    public bool VerifyHash(string inputString, string storedHash)
    {
        var generatedHash = HashString(inputString);
        return  generatedHash == storedHash;
    }
}



