// Secure Shell Command Execution Function

function executeShellCommand(command) {
  // Input Validation - Example: Sanitize input using a library like DOMPurify
  const sanitizedCommand = sanitizeInput(command); 

  return new Promise((resolve, reject) => {
    const childProcess = spawn('sh', ['-c', sanitizedCommand]); // Use appropriate shell and command
    let output = '';

    childProcess.stdout.on('data', (data) => {
      output += data.toString();
    });

    childProcess.stderr.on('data', (errorData) => {
      reject(new Error(`Command execution error: ${errorData}`));
    });

    childProcess.on('close', (code) => {
      if (code === 0) {
        resolve(output);
      } else {
        reject(new Error(`Command execution failed with code ${code}`));
      }
    });
  });
}


