fn copy_bytes(data: &mut Vec<Vec<u8>>, offset: usize, count: usize) -> Result<(), std::io::Error> {
    let mut copied_bytes = 0;
    for i in offset..offset + count {
        if i >= data.len() {
            return Err(std::io::Error::new(std::io::ErrorKind::InvalidInput, "Offset out of bounds"));
        }
        data[i].as_mut_ptr().copy_from_non_null::<u8>(buffer.as_ref(), count); // Inlining and buffer optimization
        copied_bytes += count;
    }
    Ok(())
}

