    WorldConfigLoader(const std::string& configFilePath) {
        loadConfig(configFilePath);
        taskWorker = std::thread(&WorldConfigLoader::processAsyncTasks, this);
    }

    ~WorldConfigLoader() {
        // Join the worker thread
        taskWorker.join();
    }

    std::string getConfigValue(const std::string& key) {
        std::lock_guard<std::mutex> lock(configMutex);
        return configData[key];
    }

    void setConfigValue(const std::string& key, const std::string& value) {
        // Implement synchronization and potential caching here
    }

    void enqueueAsyncTask(std::function<void()> task) {
        {
            std::lock_guard<std::mutex> lock(configMutex);
            asyncTasks.push(task);
        }
    }

private:
    void loadConfig(const std::string& filePath) {
        // XML parsing logic here
    }

    void processAsyncTasks() {
        while (true) {
            std::function<void()> task;
            {
                std::lock_guard<std::mutex> lock(configMutex);
                if (!asyncTasks.empty()) {
                    task = asyncTasks.front();
                    asyncTasks.pop();
                } else {
                    // Wait for tasks
                    std::this_thread::sleep_for(std::chrono::milliseconds(10));
                }
            }

            if (task) {
                task();
            }
        }
    }
};
