def modify_kickstart_config(config_file, parameters):
    """Modifies a Kickstart configuration file by replacing placeholders with actual values and adding an encrypted password.

    Args:
      config_file (str): Path to the Kickstart configuration file.
      parameters (dict): A dictionary where keys are placeholder names and values are replacement strings.

    Raises:
      Exception: If any sed command fails during execution.
    """
    modified_config = ""
    for key, value in parameters.items():
        command = f"sed -i 's/{key}/{value}/g' {config_file}" 
        try:
            subprocess.check_output(command, shell=True)
            print(f"Replaced '{key}' with '{value}'")
        except subprocess.CalledProcessError as e:
            raise Exception(f"Failed to modify configuration file: {e}")

    # Add encrypted password (example)
    encrypted_password = "YOUR_ENCRYPTED_PASSWORD" 
    command = f"echo 'PASSWORD={encrypted_password}' >> {config_file}"  
    try:
        subprocess.check_output(command, shell=True)
        print("Added encrypted password to configuration file")
    except subprocess.CalledProcessError as e:
        raise Exception(f"Failed to add encrypted password: {e}")


