class HttpCacheManager {
 public:
  HttpCacheManager(const std::vector<CacheService>& cacheServices) : 
      cacheServices_(cacheServices), 
      localCache_() {}

  HttpResponseMessage GetResponse(const RequestId& requestId) {
    // Cache Check (Local & Distributed)
    HttpResponseMessage response;
    if (localCache_.Find(requestId, response)) {
      return response; // Local Cache Hit
    }
    for (const auto& cacheService : cacheServices_) {
      response = cacheService.GetResponse(requestId); 
      if (!response.statusCode.IsError()) {
        // Cache Success - Store in local & Distributed caches
        localCache_.Store(requestId, response);
        return response; 
      } 
    }

