def process_messages(messages, rules):
    processed_messages = []
    threads = []
    for i in range(threading.cpu_count()):
        t = threading.Thread(target=process_batch, args=(messages[i::threading.cpu_count()], rules))
        threads.append(t)
        t.start()

    for t in threads:
        t.join()

    return processed_messages



def process_batch(messages, rules):
    global processed_messages
    for message in messages:
        if all(rule(message) for rule in rules):
            processed_messages.append(message)


