    public async Task<int> GenerateRandomValueAsync(CancellationToken cancellationToken)
    {
        if (_cache.TryGetValue(Guid.NewGuid(), out int value))
        {
            return value;
        }

        await _circuitBreaker.ExecuteAsync(async () =>
        {
            try
            {
                // Fetch UE information from external API, handling rate limiting and retries
                var ueData = await _externalApiService.GetUEDataAsync(); 

                // Process UE data to generate random value
                value = GenerateRandomValueFromUEData(ueData);

