# api_client.py
from requests import get
from time import sleep

class APIClient:
    def __init__(self, url, retries=3, backoff_factor=2):
        self.url = url
        self.retries = retries
        self.backoff_factor = backoff_factor

    async def request(self, method="GET", params=None, data=None):
        for attempt in range(self.retries + 1):
            try:
                response = await asyncio.to_thread(get, self.url, params=params, data=data, timeout=5)
                response.raise_for_status()
                return response.json()
            except requests.exceptions.RequestException as e:
                if attempt < self.retries:
                    sleep(self.backoff_factor**attempt)
                else:
                    raise e

