typedef struct {
  const char *name;
  hash_func hash_function; 
  cipher_func cipher_function;
} CryptoFunctionMetadata;

// Global mutex for thread safety
pthread_mutex_t crypto_mutex = PTHREAD_MUTEX_INITIALIZER;

// Cache of available cryptographic functions
static CryptoFunctionMetadata *crypto_functions = NULL;
static size_t num_crypto_functions = 0;

// Function to dynamically load and register cryptographic functions
void load_cryptographic_functions() {
  pthread_mutex_lock(&crypto_mutex);
  // ... Code to detect available libraries (e.g., OpenSSL, Libsodium) and register functions ...
  pthread_mutex_unlock(&crypto_mutex);
}

// Function to get a cryptographic function based on its name
CryptoFunctionMetadata *get_crypto_function(const char *name) {
  pthread_mutex_lock(&crypto_mutex);
  for (size_t i = 0; i < num_crypto_functions; ++i) {
    if (strcmp(crypto_functions[i].name, name) == 0) {
      pthread_mutex_unlock(&crypto_mutex);
      return &crypto_functions[i];
    }
  }
  pthread_mutex_unlock(&crypto_mutex);
  return NULL;
}

// Example usage:
int main() {
  load_cryptographic_functions();

  CryptoFunctionMetadata *sha256 = get_crypto_function("SHA256");
  if (sha256) {
    // ... Use the SHA256 function ...
  } else {
    fprintf(stderr, "Error: SHA256 function not found\n");
  }

  return 0;
}
