from collections import defaultdict


class Logger:
    def __init__(self):
        self.backends = defaultdict(lambda: {"level": "DEBUG", "active": True})
        self.lock = threading.RLock()

    def register_backend(self, name, backend_type, level="INFO"):
        with self.lock:
            self.backends[name] = {"backend_type": backend_type, "level": level, "active": True}

    def set_logging_level(self, category, level):
        with self.lock:
