class LogProcessor {
 public:
  LogProcessor(int numSources, int numDestinations) : 
    sources_(numSources), destinations_(numDestinations) {}

  void AddSource(std::unique_ptr<LogDataSource> source) {
    std::lock_guard<std::mutex> lock(source_mutex_);
    sources_.push_back(std::move(source));
  }

  void AddDestination(std::unique_ptr<LogDestination> destination) {
    std::lock_guard<std::mutex> lock(destination_mutex_);
    destinations_.push_back(std::move(destination));
  }

  void Start() {
    for (auto& source : sources_) {
      std::thread([this, source]() { ProcessLogStream(source); }).detach();
    }
  }

 private:
  void ProcessLogStream(std::unique_ptr<LogDataSource> source) {
    // ... Log data processing loop ...
    for (auto log_entry : source->GetLogs()) {
      ProcessLogEntry(log_entry);
    }
  }

  void ProcessLogEntry(const LogEntry& entry) {
    // ... Handle backpressure and synchronization ...
    for (auto& destination : destinations_) {
      destination->SendLog(entry);
    }
  }

  std::mutex source_mutex_;
  std::vector<std::unique_ptr<LogDataSource>> sources_;
  std::mutex destination_mutex_;
  std::vector<std::unique_ptr<LogDestination>> destinations_;
};



