public class MoSTStateLoader {

    private static final String[] WHITELISTED_SOURCES = { "local://path/to/data", "s3://bucket/key" };
    private static final ReentrantLock lock = new ReentrantLock();

    public static MoSTState loadMoSTState(String source) throws IOException, ClassNotFoundException {
        if (!isValidSource(source)) {
            throw new IllegalArgumentException("Invalid source: " + source);
        }
        lock.lock();
        try (ObjectInputStream ois = createInputStream(source)) {
            MoSTState state = (MoSTState) ois.readObject();
            verifyChecksum(state, ois); // Implement checksum verification
            return state;
        } catch (IOException | ClassNotFoundException e) {
            logException(e); 
            throw e;
        } finally {
            lock.unlock();
        }
    }

    private static boolean isValidSource(String source) {
        for (String allowedSource : WHITELISTED_SOURCES) {
            if (source.startsWith(allowedSource)) {
                return true;
            }
        }
        return false;
    }

