// Components/Dashboard.js
import React, { useState, useEffect } from 'react';
import WebSocketService from './WebSocketService';

const Dashboard = () => {
  const [data, setData] = useState({});

  useEffect(() => {
    const webSocketServices = [
      new WebSocketService('service1', '/api/v1/stream1'),
      new WebSocketService('service2', '/api/v2/stream2'),
    ];

    // Handle incoming messages from all services
    webSocketServices.forEach((service) => {
      service.onMessage((message) => {
        setData((prevData) => ({ ...prevData, [service.serviceName]: message }));
      });
    });

    // Cleanup on unmount
    return () => webSocketServices.forEach((service) => service.close());
  }, []);

  return (
    <div>
      {/* Display data from different services */}
      <h2>Service 1 Data:</h2>
      <p>{data['service1']}</p>
      <h2>Service 2 Data:</h2>
      <p>{data['service2']}</p>
    </div>
  );
};

export default Dashboard;


// Components/WebSocketService.js
class WebSocketService {
  constructor(serviceName, url) {
    this.serviceName = serviceName;
    this.socket = new WebSocket(url);
    this.onMessage = this.onMessage.bind(this);
    this.socket.onopen = () => console.log(`Connected to ${this.serviceName}`);
    this.socket.onmessage = this.onMessage;
  }

  onMessage(event) {
    // Process incoming message
  }

  close() {
    this.socket.close();
  }
}

export default WebSocketService;

