public class ServiceManager implements Runnable {
    private boolean running = false;
    private final MessageQueueClient messageQueueClient; // Kafka or RabbitMQ client

    // ... (Constructor, initialize message queue client)

    @Override
    public void run() {
        while (true) {
            if (!running) {
                startService();
                messageQueueClient.sendMessage("SERVICE_STARTED"); 
                try {
                    Thread.sleep(new Random().nextInt(5000)); // Random delay between starts
                } catch (InterruptedException e) {
                    // ... Handle interruption
                }
            } else {
                stopService();
                messageQueueClient.sendMessage("SERVICE_STOPPED"); 
                try {
