public static string GetFirstElementByXPath(string xmlDocumentPath, string xPathExpression)
{
    using (var reader = XmlReader.Create(xmlDocumentPath))
    {
        while (reader.Read())
        {
            if (reader.IsStartElement() && reader.Name == xPathExpression)
            {
                return reader.ReadInnerXml();
            }
        }
        throw new Exception($"No element found matching '{xPathExpression}' or multiple elements matched."); 
    }
}

