// DynamicValueGenerator.java

import java.util.*; 
import com.fasterxml.jackson.databind.JsonNode;
import com.fasterxml.jackson.databind.ObjectMapper;

public class DynamicValueGenerator {


    private final SchemaRegistry schemaRegistry; 
    private final ConfigurationService configurationService; 
    private final ObjectMapper objectMapper; 
    private final CacheManager cacheManager; 

    public DynamicValueGenerator(SchemaRegistry schemaRegistry, ConfigurationService configurationService) {
        this.schemaRegistry = schemaRegistry;
        this.configurationService = configurationService;
        this.objectMapper = new ObjectMapper();
        this.cacheManager = new InMemoryCacheManager(); // Choose appropriate caching mechanism
    }

    public <T> T deserialize(byte[] data, Class<T> targetClass) throws DeserializationException {
        // 1. Fetch Schema
        String schemaVersion = this.configurationService.getLatestSchemaVersion(targetClass);  
        JsonNode schema = this.schemaRegistry.getSchema(schemaVersion, targetClass);

        // 2. Validate Schema
        this.cacheManager.validateSchema(schema, targetClass); // Leverage caching for efficiency

        // 3. Deserialize Data
        try {
            return this.objectMapper.readValue(data, schema.toString(), targetClass);
        } catch (Exception e) {
            throw new DeserializationException("Error deserializing data", e);
        }
    }
}

```



