//  SensorDataProcessor.h 

#ifndef SENSOR_DATA_PROCESSOR_H
#define SENSOR_DATA_PROCESSOR_H

#include <thread>
#include <queue>
#include <mutex>
#include <condition_variable>
#include <chrono>

class SensorDataProcessor {
public:
    SensorDataProcessor(int bufferSize) : buffer(bufferSize), stopProcessing(false) {}

    void start() {
        thread = std::thread(&SensorDataProcessor::processQueue, this); 
    }

    void stop() {
        stopProcessing = true;
        thread.join();
    }

    void enqueueData(const SensorReading& data) {
        std::unique_lock<std::mutex> lock(dataMutex);
        buffer.push(data);
        cv.notify_one(); 
    }

private:
    void processQueue() {
        while (!stopProcessing) {
            std::unique_lock<std::mutex> lock(dataMutex);
            cv.wait(lock, [this] { return !buffer.empty() || stopProcessing; });
            if (stopProcessing) {
                break; 
            }
            SensorReading data = buffer.front();
            buffer.pop();
            lock.unlock();

            // Process the sensor data here...
            // Example: std::cout << "Processed data: " << data.value << std::endl;

        }
    }

    std::queue<SensorReading> buffer;
    std::mutex dataMutex;
    std::condition_variable cv;
    bool stopProcessing;
    std::thread thread;
};

#endif // SENSOR_DATA_PROCESSOR_H



```







