        // Initialize framework components based on configuration files or environment variables.
        strategy = new PrometheusLogAggregationStrategy();  
        monitor = new ThresholdMonitoringService(strategy);
        alerter = new EmailAlertingService(); 
    }

    public void log(String service, String message, LogLevel level) {
        // Create a formatted log entry
        String logEntry = String.format(LOG_FORMAT, level.toString(), System.currentTimeMillis(), service, message);
        logger.log(level, logEntry);

        // Send log to aggregation strategy for analysis and storage
        strategy.aggregateLog(logEntry); 
    }

    public void startMonitoring() {
