    public void scaleVMInstances(String applicationName, int desiredCount) {
        Map<String, VMInstance> instances = 
                providerFactory.getProvider("AWS").listInstances(applicationName);
        int currentCount = instances.size();

        if (desiredCount > currentCount) {
            allocator.allocateResources(applicationName, desiredCount - currentCount);
            serviceMesh.registerService(applicationName, desiredCount);
        } else if (desiredCount < currentCount) {
            allocator.deallocateResources(applicationName, currentCount - desiredCount);
            serviceMesh.deregisterService(applicationName, currentCount - desiredCount);
