// This is a simplified example and does not include all the features 
// listed in your requirements. Building a full-fledged C library with 
// these capabilities would be a complex undertaking.

#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <unistd.h> // for usleep (for demonstration purposes)

// Structure to hold integer data and metadata
typedef struct {
    int value;
    char source[50]; 
} DataPoint;

// Global queue for incoming data points
typedef struct {
    DataPoint* data;
    int head;
    int tail;
    pthread_mutex_t mutex; 
    pthread_cond_t cond; // Condition variable for producer/consumer synchronization
} DataQueue;

// Initialize the data queue
void init_data_queue(DataQueue* queue, int size) {
    queue->data = (DataPoint*)malloc(size * sizeof(DataPoint));
    queue->head = 0;
    queue->tail = 0;
    pthread_mutex_init(&queue->mutex, NULL);
    pthread_cond_init(&queue->cond, NULL);
}

// Add a data point to the queue
void enqueue(DataQueue* queue, DataPoint point) {
    pthread_mutex_lock(&queue->mutex);
    queue->data[queue->tail] = point;
    queue->tail = (queue->tail + 1) % (sizeof(queue->data) / sizeof(DataPoint));
    pthread_cond_signal(&queue->cond);
    pthread_mutex_unlock(&queue->mutex);
}

// Retrieve a data point from the queue
DataPoint dequeue(DataQueue* queue) {
    DataPoint point;
    pthread_mutex_lock(&queue->mutex);
    while (queue->head == queue->tail) {
        pthread_cond_wait(&queue->cond, &queue->mutex);
    }
    point = queue->data[queue->head];
    queue->head = (queue->head + 1) % (sizeof(queue->data) / sizeof(DataPoint));
    pthread_mutex_unlock(&queue->mutex);
    return point;
}



int main() {
    // Initialize a data queue (replace with your preferred size)
    DataQueue queue;
    init_data_queue(&queue, 100);

    // Example producer thread (simulates receiving data)
    pthread_t producer_thread;
    pthread_create(&producer_thread, NULL, (void *(*)(void*))produce_data, &queue); 


    // Example consumer thread (processes data)
    pthread_t consumer_thread;
    pthread_create(&consumer_thread, NULL, (void *(*)(void*))consume_data, &queue); 

    pthread_join(producer_thread, NULL);
    pthread_join(consumer_thread, NULL);


    return 0;
}



// Example producer thread function
void *produce_data(void *arg) {
    DataQueue* queue = (DataQueue*) arg;

    for (int i = 0; i < 100; ++i) {
        DataPoint point;
        point.value = i; // Sample data
        strcpy(point.source, "Network Socket"); 
        enqueue(queue, point);

        // Simulate some processing time/data rate
        usleep(100000);  
    }
    return NULL;
}



// Example consumer thread function
void *consume_data(void *arg) {
    DataQueue* queue = (DataQueue*) arg;

    while (1) {
        DataPoint point = dequeue(queue);
        printf("Processed data: %d from source %s\n", point.value, point.source);
        // Do further processing or storage based on the 'point' data
    }
    return NULL;
}



```

