// This is a simplified example and does not cover all aspects 
// of a production-ready message broker.

#include <iostream>
#include <queue>
#include <thread>
#include <mutex>
#include <condition_variable>

class MessageBroker {
public:
    void produce(const std::string& message) {
        std::unique_lock<std::mutex> lock(m);
        messageQueue.push(message);
        cv.notify_one(); 
    }

    void consume() {
        std::unique_lock<std::mutex> lock(m);
        cv.wait(lock, [this] { return !messageQueue.empty(); });
        std::string message = messageQueue.front();
        messageQueue.pop();
        std::cout << "Consumed message: " << message << std::endl;
    }

private:
    std::queue<std::string> messageQueue;
    std::mutex m;
    std::condition_variable cv;
};

int main() {
    MessageBroker broker;

    // Producer threads
    for (int i = 0; i < 5; ++i) {
        std::thread producer([&broker]() {
            for (int j = 0; j < 100; ++j) {
                broker.produce("Message " + std::to_string(j));
            }
        });
        producer.join();
    }

    // Consumer threads
    for (int i = 0; i < 3; ++i) {
        std::thread consumer([&broker]() {
            while (true) {
                broker.consume();
            }
        });
        consumer.detach(); // Let consumers run indefinitely
    }

    return 0;
}
```


