namespace Random {
class RandomNumberGenerator {
 public:
  RandomNumberGenerator(int seed = 0) : gen_(std::mt19937{seed}) {}

  // Generate a 32-bit random number
  uint32_t generate32() {
    return gen_() % UINT32_MAX;
  }

  // Generate a 64-bit random number
  uint64_t generate64() {
    return (uint64_t)gen_() << 32 | (uint64_t)gen_();
  }

 private:
  std::mt19937 gen_;
};
} 
