    public DataTableReader SendByteArrayToDatabase(byte[] byteArray, string connectionString)
    {
        using (SqlConnection connection = new SqlConnection(connectionString))
        {
            connection.Open();
            SqlCommand command = new SqlCommand("YourStoredProcName", connection);
            command.CommandType = CommandType.StoredProcedure;
            SqlParameter param = command.Parameters.Add("@byteArray", SqlDbType.VarBinary, byteArray.Length);
            param.Value = byteArray;
            using (SqlDataReader reader = command.ExecuteReader())
            {
                return reader as DataTableReader; 
            }
        }
    }
}
