#include <openssl/aes.h>
#include <openssl/sha.h>

int encrypt_data(const char *plaintext, size_t plaintext_len, const char *password, size_t password_len, unsigned char *ciphertext) {
    // 1. Derive encryption key using SHA-256
    unsigned char key[32]; // AES-256 requires a 32-byte key
    SHA256_CTX sha;
    SHA256_Init(&sha);
    SHA256_Update(&sha, password, password_len);
    SHA256_Final(key, &sha);

    // 2. Initialize AES in CBC mode
    AES_KEY aesKey;
    if (AES_set_encrypt_key(key, 256, &aesKey) < 0) {
        return -1; // Error initializing key
    }

    // 3. Encrypt plaintext using the derived key
    int len = AES_cbc_encrypt(plaintext, ciphertext, plaintext_len, &aesKey, NULL, AES_ENCRYPT);
    if (len < 0) {
        return -2; // Error encrypting data
    }

    return len;
}


```



